def find_number_combinations():
    combinations = []
    for num in range(123, 987+1):
        first = num // 100
        second = num // 10 % 10
        third = num % 10
        if second == first * 2 and third == first * 3:
            combinations.append((first, second, third))
    return sorted(combinations)
