def count_partitions(n, k, x):
    if n < k * x:
        return 0
    if k == 1:
        return 1
    if x == 1:
        return count_partitions(n - 1, k - 1, 1) + count_partitions(n - k, k, x)
    else:
        return count_partitions(n - x, k, x) + count_partitions(n, k - 1, x)
