def preorder_traversal(inorder, postorder):
    inorder_idx = {c: i for i, c in enumerate(inorder)}
    postorder_idx = {c: i for i, c in enumerate(postorder)}
    n = len(inorder)
    graph = {i: [] for i in range(n)}
    for i in range(n - 1):
        graph[inorder_idx[postorder[i]]].append(inorder_idx[postorder[i + 1]])
    return traverse(graph, 0, [])

def traverse(graph, node, path):
    path.append(node)
    for child in graph[node]:
        path = traverse(graph, child, path)
    return path
[/PYTHON]

