def calculate_arrangements(n, m, a):
    # Initialize a 2D array to store the results
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize the first row and column with 1s
    for i in range(n + 1):
        dp[i][0] = 1
    for j in range(m + 1):
        dp[0][j] = 1

    # Fill in the rest of the array using the recurrence relation
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = (dp[i - 1][j] + dp[i][j - 1]) % (10**6 + 7)
            if a[i - 1] >= j:
                dp[i][j] = (dp[i][j] - dp[i - 1][j - a[i - 1]] + (10**6 + 7)) % (10**6 + 7)

    # Return the last entry in the array
    return dp[n][m]
